const raw = $input.first().json;
let input = raw.body ?? raw;
if (typeof input === 'string') input = JSON.parse(input);

const telemetry = input.telemetry_history || [];
const baseHours = Number(input.base_shelf_life_days || 10) * 24;
const transitHours = Number(input.current_transit_hours || 0);

let sensorStatus = "ONLINE";
let readings = telemetry;
if (readings.length === 0) {
  sensorStatus = "BLACKOUT_DRIFT";
  readings = [{ temp: 9.5, humidity: 80.0 }]; // worst-case fallback
}

const R = 8.314;
const Ea = 65000;
const baseKelvin = 277.15; // 4°C target
const decayRates = readings.map(r => {
  const kelvin = Number(r.temp ?? 4.0) + 273.15;
  return Math.exp((-Ea / R) * ((1 / kelvin) - (1 / baseKelvin)));
});
const avgDecay = decayRates.reduce((a, b) => a + b, 0) / decayRates.length;

const effectiveSpentHours = transitHours * avgDecay;
const remainingHours = Math.max(0, baseHours - effectiveSpentHours);
const disruption = remainingHours < 48;

return [{
  json: {
    ...input,
    remaining_shelf_life_hours: Math.round(remainingHours * 10) / 10,
    disruption_detected: disruption,
    sensor_status: sensorStatus
  }
}];

const agent = $input.first().json;
const upstream = $('Code in JavaScript').first().json;   // must match your Arrhenius node's name exactly
const remaining = upstream.remaining_shelf_life_hours;

// standard options, used only if the AI fails or returns broken JSON
const fallbackPorts = [
  { port: "Port Rotterdam", extra_hours: 4,  salvage_pct: 0.85 },
  { port: "Port Antwerp",   extra_hours: 6,  salvage_pct: 0.75 },
  { port: "Port Hamburg",   extra_hours: 10, salvage_pct: 0.60 }
];

// parse the Agent's JSON string output
let candidatePorts;
let aiStatus = "AI_PROPOSED";
try {
  const text = String(agent.output ?? '').replace(/```json|```/g, '').trim();
  candidatePorts = JSON.parse(text);
} catch (e) {
  candidatePorts = fallbackPorts;
  aiStatus = "AI_UNAVAILABLE_USING_STANDARD_OPTIONS";
}

// legality lookup (matches the real port names the Agent was told to use)
const legalityByPort = {
  "Port Rotterdam": true,
  "Port Antwerp": true,
  "Port Hamburg": false   // e.g. import restrictions on this cargo type
};

const legalOptions = candidatePorts
  .map(p => ({ ...p, legal_for_cargo: legalityByPort[p.port] ?? false }))
  .filter(p => p.legal_for_cargo);

const viableOptions = legalOptions.filter(
  p => Number(p.extra_hours) < remaining
);

const ranked = viableOptions.sort((a, b) => b.salvage_pct - a.salvage_pct);

return [{
  json: {
    ...upstream,
    remaining_shelf_life_hours: remaining,
    ai_status: aiStatus,
    candidate_options: ranked,
    best_option: ranked[0] || null,
    needs_manual_decision: ranked.length === 0,
    gate_note: `Filtered ${candidatePorts.length - legalOptions.length} illegal option(s); ${ranked.length} legal+viable option(s) remain.`
  }
}];
